#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *left;
    struct Node *right;
} Node;

Node *new_node(int value) {
    Node *p = (Node *)malloc(sizeof(Node));
    if (p == NULL) {
        return NULL;
    }
    p->value = value;
    p->left = NULL;
    p->right = NULL;
    return p;
}

Node *insert(Node *root, int value) {
    if (root == NULL) {
        return new_node(value);
    }
    if (value > root->value) {
        root->left = insert(root->left, value);
    } else if (value < root->value) {
        root->right = insert(root->right, value);
    }
    return root;
}

void inorder(Node *root) {
    if (root == NULL) {
        return;
    }
    inorder(root->left);
    printf("%d ", root->value);
    inorder(root->right);
}

int main(void) {
    Node *root = NULL;
    int values[5] = {{a}, {b}, {c}, {d}, {e}};
    for (int i = 0; i < 5; i++) {
        root = insert(root, values[i]);
    }

    printf("中序：");
    inorder(root);
    printf("\n");
    return 0;
}

